25: KHRicdVendor *khrIcdVendors = NULL;
26: static KHRicdVendor *lastVendor = NULL;
27: static int khrDisableLibraryUnloading = 0;
28: static int khrForceLegacyTermination = 0;
29: 
30: #if defined(CL_ENABLE_LAYERS)
