34: static inline int khrIcdCheckEnvTrue(const char *variable)
35: {
36:     return (variable && (strcmp(variable, "True") == 0 ||
37:                 strcmp(variable, "true") == 0 ||
38:                 strcmp(variable, "T") == 0 ||
39:                 strcmp(variable, "1") == 0));
40: }
41: 
42: // Set a given flag if the given environement variable is true
43: static void khrInitializeFlagWithEnv(int *flag, const char *variable)
44: {
45:     char *variableStr = khrIcd_getenv(variable);
46:     if (khrIcdCheckEnvTrue(variableStr))
47:     {
48:         *flag = 1;
49:     }
50:     if (variableStr)
51:     {
52:         khrIcd_free_getenv(variableStr);
53:     }
54: }
55: 
56: void khrIcdInitializeEnvOptions(void)
57: {
58:     khrInitializeFlagWithEnv(&khrEnableTrace, "OCL_ICD_ENABLE_TRACE");
59:     khrInitializeFlagWithEnv(&khrDisableLibraryUnloading, "OCL_ICD_DISABLE_DYNAMIC_LIBRARY_UNLOADING");
60:     khrInitializeFlagWithEnv(&khrForceLegacyTermination, "OCL_ICD_FORCE_LEGACY_TERMINATION");
61: }
