70: void khrIcdVendorAdd(const char *libraryName)
71: {
72:     void *library = NULL;
73:     cl_int result = CL_SUCCESS;
74:     pfn_clGetExtensionFunctionAddress p_clGetExtensionFunctionAddress = NULL;
75:     pfn_clIcdGetPlatformIDs p_clIcdGetPlatformIDs = NULL;
76: #if defined(CL_ENABLE_LOADER_MANAGED_DISPATCH)
77:     clIcdGetFunctionAddressForPlatformKHR_fn p_clIcdGetFunctionAddressForPlatform = NULL;
78:     clIcdSetPlatformDispatchDataKHR_fn p_clIcdSetPlatformDispatchData = NULL;
79: #endif
80:     cl_uint i = 0;
81:     cl_uint platformCount = 0;
82:     cl_platform_id *platforms = NULL;
83:     KHRicdVendor *vendorIterator = NULL;
84: 
85:     // require that the library name be valid
86:     if (!libraryName)
87:     {
88:         goto Done;
89:     }
90:     KHR_ICD_TRACE("attempting to add vendor %s...\n", libraryName);
91: 
92:     // load its library and query its function pointers
93:     library = khrIcdOsLibraryLoad(libraryName);
94:     if (!library)
95:     {
96:         KHR_ICD_TRACE("failed to load library %s\n", libraryName);
97:         goto Done;
98:     }
99: 
100:     // ensure that we haven't already loaded this vendor
101:     for (vendorIterator = khrIcdVendors; vendorIterator; vendorIterator = vendorIterator->next)
102:     {
103:         if (vendorIterator->library == library)
104:         {
105:             KHR_ICD_TRACE("already loaded vendor %s, nothing to do here\n", libraryName);
106:             goto Done;
107:         }
108:     }
109: 
110:     // get the library's clGetExtensionFunctionAddress pointer
111:     p_clGetExtensionFunctionAddress = (pfn_clGetExtensionFunctionAddress)(size_t)khrIcdOsLibraryGetFunctionAddress(library, "clGetExtensionFunctionAddress");
112:     if (!p_clGetExtensionFunctionAddress)
113:     {
114:         KHR_ICD_TRACE("failed to get function address clGetExtensionFunctionAddress\n");
115:         goto Done;
116:     }
117: 
118:     // use that function to get the clIcdGetPlatformIDsKHR function pointer
119:     p_clIcdGetPlatformIDs = (pfn_clIcdGetPlatformIDs)(size_t)p_clGetExtensionFunctionAddress("clIcdGetPlatformIDsKHR");
120:     if (!p_clIcdGetPlatformIDs)
121:     {
122:         KHR_ICD_TRACE("failed to get extension function address clIcdGetPlatformIDsKHR\n");
123:         goto Done;
124:     }
125: 
126: #if defined(CL_ENABLE_LOADER_MANAGED_DISPATCH)
127:     // try to get clIcdGetFunctionAddressForPlatformKHR and clIcdSetPlatformDispatchDataKHR to detect cl_khr_icd2 support
128:     p_clIcdGetFunctionAddressForPlatform = (clIcdGetFunctionAddressForPlatformKHR_fn)(size_t)p_clGetExtensionFunctionAddress("clIcdGetFunctionAddressForPlatformKHR");
129:     p_clIcdSetPlatformDispatchData = (clIcdSetPlatformDispatchDataKHR_fn)(size_t)p_clGetExtensionFunctionAddress("clIcdSetPlatformDispatchDataKHR");
130: #endif
131: 
132:     // query the number of platforms available and allocate space to store them
133:     result = p_clIcdGetPlatformIDs(0, NULL, &platformCount);
134:     if (CL_SUCCESS != result)
135:     {
136:         KHR_ICD_TRACE("failed clIcdGetPlatformIDs\n");
137:         goto Done;
138:     }
139:     platforms = (cl_platform_id *)malloc(platformCount * sizeof(cl_platform_id) );
140:     if (!platforms)
141:     {
142:         KHR_ICD_TRACE("failed to allocate memory\n");
143:         goto Done;
144:     }
145:     memset(platforms, 0, platformCount * sizeof(cl_platform_id) );
146:     result = p_clIcdGetPlatformIDs(platformCount, platforms, NULL);
147:     if (CL_SUCCESS != result)
148:     {
149:         KHR_ICD_TRACE("failed clIcdGetPlatformIDs\n");
150:         goto Done;
151:     }
152: 
153:     // for each platform, add it
154:     for (i = 0; i < platformCount; ++i)
155:     {
156:         KHRicdVendor* vendor = NULL;
157:         char *extensions;
158:         size_t extensionsSize;
159:         char *suffix;
160:         size_t suffixSize;
161: 
162:         // skip NULL platforms and non dispatchable platforms
163:         if (!platforms[i] || !platforms[i]->dispatch)
164:         {
165:             continue;
166:         }
167: 
168: #if defined(CL_ENABLE_LOADER_MANAGED_DISPATCH)
169:         if (KHR_ICD2_HAS_TAG(platforms[i]) && !p_clIcdGetFunctionAddressForPlatform)
170:         {
