502: static char *loader_get_next_path(char *path) {
503:     size_t len;
504:     char *next;
505: 
506:     if (path == NULL) return NULL;
507:     next = strchr(path, PATH_SEPARATOR);
508:     if (next == NULL) {
509:         len = strlen(path);
510:         next = path + len;
511:     } else {
512:         *next = '\0';
513:         next++;
514:     }
515: 
516:     return next;
